import random

def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_score = 0
    opp_score = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    coop_count = 0
    defect_count = 0
    opp_coop_count = 0
    opp_defect_count = 0
    for a, b in history:
        if a == 'C':
            coop_count += 1
        else:
            defect_count += 1
        if b == 'C':
            opp_coop_count += 1
        else:
            opp_defect_count += 1

    last_a, last_b = history[-1]

    if n == 1:
        return 'C'

    if n >= 2:
        prev_a, prev_b = history[-2]
        if prev_b == 'D' and last_b == 'D':
            return 'D'

    if n >= 5:
        recent_opp_defects = 0
        for i in range(n - 5, n):
            if history[i][1] == 'D':
                recent_opp_defects += 1
        if recent_opp_defects >= 3:
            return 'D'

    if opp_defect_count == 0:
        return 'C'

    if opp_coop_count > 0:
        ratio_num = opp_coop_count
        ratio_den = n
        if ratio_num * 2 >= ratio_den:
            if last_b == 'D':
                if rng.random() < 0.1:
                    return 'D'
                return 'C'
            return 'C'

    if last_b == 'D':
        if n >= 3:
            d_count = 0
            for i in range(max(0, n - 3), n):
                if history[i][1] == 'D':
                    d_count += 1
            if d_count >= 2:
                return 'D'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    if opp_defect_count * 2 > n:
        return 'D'

    remainder = 100 - n
    if remainder <= 2:
        if my_score < opp_score:
            return 'D'
        return 'C'
    if remainder <= 5:
        if my_score + 2 < opp_score:
            return 'D'
        return 'C'

    return 'C'

